/* ============================================================================
   PLAN_DESARROLLO_5B  (28/10/2026)  -- completa PLAN_DESARROLLO_5
   ----------------------------------------------------------------------------
   PLAN_DESARROLLO_5 quedo aplicado salvo el modal "Trabajo de la visita" (boceto B):
   ese bloque es largo y REPLACE no acepta textos de mas de 4000 caracteres (el aviso
   "String or binary data would be truncated"). Este script lo reemplaza ubicando
   su inicio y su fin. Si algo no coincide, no cambia nada. Re-ejecutable.  SSMS: F5.
   ============================================================================ */
USE [MuhlePROD];
SET NOCOUNT ON;
GO
DECLARE @D NVARCHAR(MAX) = OBJECT_DEFINITION(OBJECT_ID('dbo.VCT_MAIN_PROYECTO_V360')),
        @NEW NVARCHAR(MAX), @A NVARCHAR(200), @Z NVARCHAR(400), @i INT, @j INT, @s INT, @p INT;
SET @A = CONVERT(NVARCHAR(MAX), N'')+ N'        SELECT @AGW = ISNULL((';
SET @Z = CONVERT(NVARCHAR(MAX), N'')+ N'            FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), '''');' + NCHAR(10) + N'        SET @AG_WM';
IF @D IS NULL
    PRINT 'FALLO: no se encontro dbo.VCT_MAIN_PROYECTO_V360.';
ELSE IF CHARINDEX(N'PL_DES_V5: trabajo de la visita', @D) > 0
    PRINT 'OK   el modal Trabajo de la visita ya estaba actualizado: no se hizo nada.';
ELSE IF CHARINDEX(N'PL_DES_V5', @D) = 0
    PRINT 'FALLO: falta aplicar antes PLAN_DESARROLLO_5.sql. No se cambio nada.';
ELSE
BEGIN
    SET @D = REPLACE(@D, NCHAR(13) + NCHAR(10), NCHAR(10));
    SET @i = CHARINDEX(@A, @D);
    SET @j = CASE WHEN @i > 0 THEN CHARINDEX(@Z, @D, @i) ELSE 0 END;
    IF @i = 0 OR @j = 0 OR CHARINDEX(@A, @D, @i + 1) > 0 OR CHARINDEX(N'Planificado para la visita', SUBSTRING(@D, @i, @j - @i)) = 0
        PRINT 'FALLO: no se encontro el bloque del modal Trabajo de la visita. No se cambio nada.';
    ELSE
    BEGIN
        SET @NEW = CONVERT(NVARCHAR(MAX), N'')+ N'        /* PL_DES_V5: trabajo de la visita (boceto B): indicadores, por consultor, trabajado y lo que queda para la proxima visita */' + NCHAR(10) + N'        SELECT @AGW = ISNULL((' + NCHAR(10) + N'            SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw" data-pv-agw="'' + CONVERT(VARCHAR(20), A.ID) + ''" hidden''' + NCHAR(10) + N'                 + '' data-x="'' + REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(A.INST + CASE WHEN A.CONS_TXT <> '''' THEN '' - '' + A.CONS_TXT ELSE '''' END,''\'',''/''),''"'',''''''''),CHAR(10),'' ''),CHAR(13),'' ''),''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''"''' + NCHAR(10) + N'                 + '' data-d1="'' + CONVERT(VARCHAR(10), A.DESDE, 120) + ''" data-d2="'' + CONVERT(VARCHAR(10), A.HASTA, 120) + ''"''' + NCHAR(10) + N'                 + '' data-tit="Visita del '' + CONVERT(VARCHAR(10), A.DESDE, 103) + CASE WHEN A.HASTA > A.DESDE THEN '' al '' + CONVERT(VARCHAR(10), A.HASTA, 103) ELSE '''' END + ''"''' + NCHAR(10) + N'                 + '' data-sub="'' + REPLACE(REPLACE(REPLACE(REPLACE(A.INST + '' - '' + CASE A.SIT WHEN ''e'' THEN ''Ejecutada'' WHEN ''c'' THEN ''Confirmada'' ELSE ''Pendiente'' END + CASE WHEN A.CONS_TXT <> '''' THEN '' - '' + A.CONS_TXT ELSE '''' END,''&'',''&amp;''),''"'',''&quot;''),''<'',''&lt;''),''>'',''&gt;'') + ''">''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-k"><div><small>Horas de la visita</small><b>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), A.HT)), ''.0'', '''') + '' h</b><em>'' + CONVERT(VARCHAR(10), ISNULL(NC.N, 0)) + '' consultor'' + CASE WHEN ISNULL(NC.N, 0) = 1 THEN '''' ELSE ''es'' END + ''</em></div>''' + NCHAR(10) + N'                 + ''<div><small>Volcadas en desarrollos</small><b>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(R.H, 0))), ''.0'', '''') + '' h</b><em>'' + CONVERT(VARCHAR(10), CASE WHEN A.HT > 0 THEN CONVERT(INT, ROUND(ISNULL(R.H, 0) * 100.0 / A.HT, 0)) ELSE 0 END) + '' %</em></div>''' + NCHAR(10) + N'                 + ''<div><small>Sin detallar (informe)</small><b>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), CASE WHEN A.HT > ISNULL(R.H, 0) THEN A.HT - ISNULL(R.H, 0) ELSE 0 END)), ''.0'', '''') + '' h</b></div>''' + NCHAR(10) + N'                 + ''<div><small>Transcurrido desde 1&ordf; visita</small><b>'' + CASE WHEN @F_V1 IS NULL THEN ''-'' ELSE CONVERT(VARCHAR(10), DATEDIFF(DAY, @F_V1, A.DESDE)) + '' d&iacute;as'' END + ''</b>''' + NCHAR(10) + N'                 + CASE WHEN @F_V1 IS NULL THEN '''' ELSE ''<em>desde '' + CONVERT(VARCHAR(5), @F_V1, 103) + ''</em>'' END + ''</div></div>''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-sec">Por consultor</div>''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-tb"><div class="vct-pv-agw-tr is-h"><span>Consultor</span><span>Visita</span><span>Detallado</span><span>Sin detallar</span><span>Uso</span></div>''' + NCHAR(10) + N'                 + ISNULL((SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw-tr"><span><b>'' + REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</b>''' + NCHAR(10) + N'                                      + CASE WHEN EXISTS (SELECT 1 FROM #EQ Q WHERE Q.TIPO = ''CONSULTOR'' AND Q.ID_ENT = VC.ID_CONSULTOR AND Q.ROL_COD = ''CONSULTOR_LIDER'') THEN ''<i class="vct-pv-agw-lid">L&iacute;der</i>'' ELSE '''' END + ''</span>''' + NCHAR(10) + N'                                      + ''<span>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(VC.HORAS_EJECUTADAS, ISNULL(VC.HORAS_PLANIFICADAS, 0)))), ''.0'', '''') + '' h</span>''' + NCHAR(10) + N'                                      + ''<span>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(DD.H, 0))), ''.0'', '''') + '' h</span>''' + NCHAR(10) + N'                                      + ''<span>'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), CASE WHEN ISNULL(VC.HORAS_EJECUTADAS, ISNULL(VC.HORAS_PLANIFICADAS, 0)) > ISNULL(DD.H, 0) THEN ISNULL(VC.HORAS_EJECUTADAS, ISNULL(VC.HORAS_PLANIFICADAS, 0)) - ISNULL(DD.H, 0) ELSE 0 END)), ''.0'', '''') + '' h</span>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-bar"><span class="is-plan" style="width:'' + CONVERT(VARCHAR(10), CASE WHEN ISNULL(VC.HORAS_EJECUTADAS, ISNULL(VC.HORAS_PLANIFICADAS, 0)) <= 0 THEN 0' + NCHAR(10) + N'                                             WHEN ISNULL(DD.H, 0) >= ISNULL(VC.HORAS_EJECUTADAS, ISNULL(VC.HORAS_PLANIFICADAS, 0)) THEN 100' + NCHAR(10) + N'                                             ELSE CONVERT(INT, ROUND(ISNULL(DD.H, 0) * 100.0 / ISNULL(VC.HORAS_EJECUTADAS, ISNULL(VC.HORAS_PLANIFICADAS, 0)), 0)) END) + ''%"></span></span></div>''' + NCHAR(10) + N'                                 FROM dbo.VCT_PROYECTOS_VISITAS_CONSULTORES VC WITH(NOLOCK)' + NCHAR(10) + N'                                 OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = VC.ID_CONSULTOR) Y' + NCHAR(10) + N'                                 OUTER APPLY (SELECT SUM(D.HORAS) AS H FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) WHERE D.ID_VISITA = A.ID AND D.ID_CONSULTOR = VC.ID_CONSULTOR AND D.TIPO = ''REALIZADO'') DD' + NCHAR(10) + N'                                 WHERE VC.ID_VISITA = A.ID ORDER BY Y.NOM' + NCHAR(10) + N'                                 FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), '''') + ''</div>''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-cols">''' + NCHAR(10) + N'                 + ''<div class="vct-pv-agw-col"><div class="vct-pv-agw-h">&#10003; Trabajado en esta visita<span class="vct-360-badge is-active">'' + CONVERT(VARCHAR(10), ISNULL(R.NR, 0)) + '' desarrollo'' + CASE WHEN ISNULL(R.NR, 0) = 1 THEN '''' ELSE ''s'' END + '' &middot; '' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(R.H, 0))), ''.0'', '''') + '' h</span></div>''' + NCHAR(10) + N'                 + ISNULL(NULLIF(ISNULL((SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw-it"><div>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-ix">'' + CASE WHEN ISNULL(I.CODIGO_ITEM, '''') <> '''' THEN REPLACE(REPLACE(REPLACE(I.CODIGO_ITEM,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + '' &middot; '' ELSE '''' END + REPLACE(REPLACE(REPLACE(ISNULL(I.TITULO, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span>''' + NCHAR(10) + N'                                      + ''<b>'' + REPLACE(REPLACE(REPLACE(D.TITULO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</b>''' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.DESARROLLO, '''') <> '''' THEN ''<p>'' + REPLACE(REPLACE(REPLACE(LEFT(D.DESARROLLO, 600),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</p>'' ELSE '''' END' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-who">'' + REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'')' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.PROXIMO_PASO, '''') <> '''' THEN '' &middot; Pr&oacute;ximo: '' + REPLACE(REPLACE(REPLACE(D.PROXIMO_PASO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') ELSE '''' END + ''</span></div>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-hs">'' + REPLACE(CONVERT(VARCHAR(20), CONVERT(DECIMAL(9,1), ISNULL(D.HORAS, 0))), ''.0'', '''') + '' h'' + ''</span></div>''' + NCHAR(10) + N'                                 FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK)' + NCHAR(10) + N'                                 INNER JOIN dbo.VCT_ACCIONES AC WITH(NOLOCK) ON AC.ID = D.ID_ACCION' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_PLAN_ITEMS I WITH(NOLOCK) ON I.ID = AC.ID_PLAN_ITEM' + NCHAR(10) + N'                                 OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = D.ID_CONSULTOR) Y' + NCHAR(10) + N'                                 WHERE D.ID_VISITA = A.ID AND D.TIPO = ''REALIZADO'' ORDER BY I.ORDEN, D.ID' + NCHAR(10) + N'                                 FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), ''''), ''''), ''<div class="vct-plt-empty">Sin desarrollos realizados en esta visita.</div>'')' + NCHAR(10) + N'                 + ''</div>''' + NCHAR(10) + N'                 + CASE WHEN A.DESDE > @HOY' + NCHAR(10) + N'                        THEN ''<div class="vct-pv-agw-col"><div class="vct-pv-agw-h">Planificado para esta visita<span class="vct-360-badge is-planned">'' + CONVERT(VARCHAR(10), ISNULL(R.NP, 0)) + ''</span></div>''' + NCHAR(10) + N'                           + ISNULL(NULLIF(ISNULL((SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw-it"><div>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-ix">'' + CASE WHEN ISNULL(I.CODIGO_ITEM, '''') <> '''' THEN REPLACE(REPLACE(REPLACE(I.CODIGO_ITEM,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + '' &middot; '' ELSE '''' END + REPLACE(REPLACE(REPLACE(ISNULL(I.TITULO, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span>''' + NCHAR(10) + N'                                      + ''<b>'' + REPLACE(REPLACE(REPLACE(D.TITULO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</b>''' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.DESARROLLO, '''') <> '''' THEN ''<p>'' + REPLACE(REPLACE(REPLACE(LEFT(D.DESARROLLO, 600),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</p>'' ELSE '''' END' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-who">'' + REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'')' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.PROXIMO_PASO, '''') <> '''' THEN '' &middot; Pr&oacute;ximo: '' + REPLACE(REPLACE(REPLACE(D.PROXIMO_PASO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') ELSE '''' END + ''</span></div>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-hs">'' + ''&ndash;'' + ''</span></div>''' + NCHAR(10) + N'                                 FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK)' + NCHAR(10) + N'                                 INNER JOIN dbo.VCT_ACCIONES AC WITH(NOLOCK) ON AC.ID = D.ID_ACCION' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_PLAN_ITEMS I WITH(NOLOCK) ON I.ID = AC.ID_PLAN_ITEM' + NCHAR(10) + N'                                 OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = D.ID_CONSULTOR) Y' + NCHAR(10) + N'                                 WHERE D.ID_VISITA = A.ID AND D.TIPO = ''PLANIFICADO'' ORDER BY I.ORDEN, D.ID' + NCHAR(10) + N'                                 FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), ''''), ''''), ''<div class="vct-plt-empty">Nada planificado para esta visita.</div>'')' + NCHAR(10) + N'                           + ''</div>''' + NCHAR(10) + N'                        ELSE ''<div class="vct-pv-agw-col"><div class="vct-pv-agw-h">&rarr; Para trabajar en la pr&oacute;xima visita'' + CASE WHEN NX.FD IS NOT NULL THEN '' ('' + CONVERT(VARCHAR(5), NX.FD, 103) + '')'' ELSE '''' END' + NCHAR(10) + N'                           + ''<span class="vct-360-badge is-planned">'' + CONVERT(VARCHAR(10), ISNULL(NXP.N, 0) + ISNULL(PP.N, 0)) + ''</span></div>''' + NCHAR(10) + N'                           + ISNULL(NULLIF(ISNULL((SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw-it"><div>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-ix">'' + CASE WHEN ISNULL(I.CODIGO_ITEM, '''') <> '''' THEN REPLACE(REPLACE(REPLACE(I.CODIGO_ITEM,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + '' &middot; '' ELSE '''' END + REPLACE(REPLACE(REPLACE(ISNULL(I.TITULO, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span>''' + NCHAR(10) + N'                                      + ''<b>'' + REPLACE(REPLACE(REPLACE(D.TITULO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</b>''' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.DESARROLLO, '''') <> '''' THEN ''<p>'' + REPLACE(REPLACE(REPLACE(LEFT(D.DESARROLLO, 600),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</p>'' ELSE '''' END' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-who">'' + REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'')' + NCHAR(10) + N'                                      + CASE WHEN ISNULL(D.PROXIMO_PASO, '''') <> '''' THEN '' &middot; Pr&oacute;ximo: '' + REPLACE(REPLACE(REPLACE(D.PROXIMO_PASO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') ELSE '''' END + ''</span></div>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-hs">'' + ''&ndash;'' + ''</span></div>''' + NCHAR(10) + N'                                 FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK)' + NCHAR(10) + N'                                 INNER JOIN dbo.VCT_ACCIONES AC WITH(NOLOCK) ON AC.ID = D.ID_ACCION' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_PLAN_ITEMS I WITH(NOLOCK) ON I.ID = AC.ID_PLAN_ITEM' + NCHAR(10) + N'                                 OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = D.ID_CONSULTOR) Y' + NCHAR(10) + N'                                 WHERE NX.ID IS NOT NULL AND D.ID_VISITA = NX.ID AND D.TIPO = ''PLANIFICADO'' ORDER BY I.ORDEN, D.ID' + NCHAR(10) + N'                                 FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), '''')' + NCHAR(10) + N'                                    + ISNULL((SELECT CONVERT(VARCHAR(MAX), '''') + ''<div class="vct-pv-agw-it is-paso"><div>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-ix">'' + CASE WHEN ISNULL(I.CODIGO_ITEM, '''') <> '''' THEN REPLACE(REPLACE(REPLACE(I.CODIGO_ITEM,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + '' &middot; '' ELSE '''' END + REPLACE(REPLACE(REPLACE(ISNULL(I.TITULO, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</span>''' + NCHAR(10) + N'                                      + ''<b>'' + REPLACE(REPLACE(REPLACE(D.PROXIMO_PASO,''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + ''</b>''' + NCHAR(10) + N'                                      + ''<span class="vct-pv-agw-who">'' + REPLACE(REPLACE(REPLACE(ISNULL(Y.NOM, ''''),''&'',''&amp;''),''<'',''&lt;''),''>'',''&gt;'') + '' &middot; pr&oacute;ximo paso de esta visita</span></div><span class="vct-pv-agw-hs">&ndash;</span></div>''' + NCHAR(10) + N'                                 FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK)' + NCHAR(10) + N'                                 INNER JOIN dbo.VCT_ACCIONES AC WITH(NOLOCK) ON AC.ID = D.ID_ACCION' + NCHAR(10) + N'                                 LEFT JOIN dbo.VCT_PROYECTOS_PLAN_ITEMS I WITH(NOLOCK) ON I.ID = AC.ID_PLAN_ITEM' + NCHAR(10) + N'                                 OUTER APPLY (SELECT TOP 1 LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(150),C.APELLIDOS),'''') + '', '' + ISNULL(CONVERT(VARCHAR(150),C.NOMBRES),''''))) AS NOM FROM dbo.VCT_CONSULTORES C WITH(NOLOCK) WHERE C.ID = D.ID_CONSULTOR) Y' + NCHAR(10) + N'                                 WHERE D.ID_VISITA = A.ID AND D.TIPO = ''REALIZADO'' AND ISNULL(D.PROXIMO_PASO, '''') <> '''' ORDER BY I.ORDEN, D.ID' + NCHAR(10) + N'                                 FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), ''''), ''''),' + NCHAR(10) + N'                                    ''<div class="vct-plt-empty">'' + CASE WHEN NX.ID IS NULL THEN ''No hay una pr&oacute;xima visita cargada en la agenda.'' ELSE ''Nada planificado para la pr&oacute;xima visita.'' END + ''</div>'')' + NCHAR(10) + N'                           + ''</div>'' END' + NCHAR(10) + N'                 + ''</div></div>''' + NCHAR(10) + N'            FROM #AGV A' + NCHAR(10) + N'            OUTER APPLY (SELECT SUM(CASE WHEN D.TIPO = ''REALIZADO'' THEN ISNULL(D.HORAS, 0) ELSE 0 END) AS H,' + NCHAR(10) + N'                                SUM(CASE WHEN D.TIPO = ''REALIZADO'' THEN 1 ELSE 0 END) AS NR,' + NCHAR(10) + N'                                SUM(CASE WHEN D.TIPO = ''PLANIFICADO'' THEN 1 ELSE 0 END) AS NP' + NCHAR(10) + N'                         FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) WHERE D.ID_VISITA = A.ID) R' + NCHAR(10) + N'            OUTER APPLY (SELECT COUNT(*) AS N FROM dbo.VCT_PROYECTOS_VISITAS_CONSULTORES VC WITH(NOLOCK) WHERE VC.ID_VISITA = A.ID) NC' + NCHAR(10) + N'            OUTER APPLY (SELECT TOP 1 V2.ID, V2.FECHA_DESDE AS FD FROM dbo.VCT_PROYECTOS_VISITAS V2 WITH(NOLOCK)' + NCHAR(10) + N'                         WHERE V2.ID_PROYECTO = @ID_PROYECTO AND CONVERT(DATE, V2.FECHA_DESDE) > CONVERT(DATE, A.DESDE)' + NCHAR(10) + N'                           AND UPPER(LTRIM(RTRIM(ISNULL(V2.ESTADO,'''')))) NOT IN (''CANCELADO'',''ANULADO'')' + NCHAR(10) + N'                         ORDER BY V2.FECHA_DESDE, V2.ID) NX' + NCHAR(10) + N'            OUTER APPLY (SELECT COUNT(*) AS N FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) WHERE NX.ID IS NOT NULL AND D.ID_VISITA = NX.ID AND D.TIPO = ''PLANIFICADO'') NXP' + NCHAR(10) + N'            OUTER APPLY (SELECT COUNT(*) AS N FROM dbo.VCT_ACCIONES_DESARROLLO D WITH(NOLOCK) WHERE D.ID_VISITA = A.ID AND D.TIPO = ''REALIZADO'' AND ISNULL(D.PROXIMO_PASO, '''') <> '''') PP' + NCHAR(10) + N'            ORDER BY A.DESDE, A.ID' + NCHAR(10) + N'            FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), '''');';
        SET @D = STUFF(@D, @i, @j - @i + LEN(N'            FOR XML PATH(''''), TYPE).value(''.'',''VARCHAR(MAX)''), '''');'), @NEW);
        SET @s = CHARINDEX(N'PROCEDURE', @D);
        SET @p = CASE WHEN @s > 40 THEN @s - 40 ELSE 1 END;
        IF CHARINDEX(N'CREATE', SUBSTRING(@D, @p, 40)) > 0 AND CHARINDEX(N'OR ALTER', SUBSTRING(@D, @p, 40)) = 0
            SET @D = STUFF(@D, @p + CHARINDEX(N'CREATE', SUBSTRING(@D, @p, 40)) - 1, 6, N'ALTER ');
        BEGIN TRY
            EXEC sys.sp_executesql @D;
            PRINT 'OK   VCT_MAIN_PROYECTO_V360: modal Trabajo de la visita actualizado (boceto B).';
        END TRY
        BEGIN CATCH
            PRINT 'FALLO al actualizar VCT_MAIN_PROYECTO_V360 (no se cambio): ' + ERROR_MESSAGE() + ' (linea ' + CONVERT(VARCHAR(10), ERROR_LINE()) + ')';
        END CATCH;
    END;
END;
GO
